export type PromiseStatus = 'substantially_fulfilled' | 'partially_fulfilled' | 'not_fulfilled' | 'insufficient_evidence';
export type PromiseRecord = { id:string; party:PartyKey; commitment:string; document:string; status:PromiseStatus; assessment:string; evidenceStrength:'A'|'B'|'C'|'D'; sourceIds:string[] };
export const promises: PromiseRecord[] = [
  { id:'upa-employment-guarantee', party:'congress', commitment:'Create a national employment guarantee for rural households.', document:'UPA National Common Minimum Programme, 2004', status:'substantially_fulfilled', assessment:'Parliament enacted the rural employment guarantee in 2005 and implementation began in 2006. This assessment concerns enactment, not every implementation outcome.', evidenceStrength:'A', sourceIds:['ncmp-budget','mgnrega'] },
  { id:'upa-information-law', party:'congress', commitment:'Enact a stronger right-to-information framework.', document:'UPA National Common Minimum Programme, 2004', status:'substantially_fulfilled', assessment:'The Right to Information Act was enacted in 2005 and created enforceable access procedures and information commissions.', evidenceStrength:'A', sourceIds:['ncmp-budget','india-code'] },
  { id:'upa-food-security', party:'congress', commitment:'Provide a legal framework for food security.', document:'Indian National Congress Manifesto, 2009', status:'substantially_fulfilled', assessment:'The National Food Security Act was enacted in 2013. This assessment does not judge coverage quality or implementation outcomes.', evidenceStrength:'A', sourceIds:['inc-2009','india-code'] },
  { id:'upa-womens-reservation', party:'congress', commitment:'Pass constitutional reservation for women in the Lok Sabha and state assemblies.', document:'Indian National Congress Manifesto, 2009', status:'not_fulfilled', assessment:'The bill passed the Rajya Sabha in 2010 but did not become law during the UPA term.', evidenceStrength:'A', sourceIds:['inc-2009','india-code'] },
  { id:'upa-health', party:'congress', commitment:'Increase access to public health services, particularly in rural areas.', document:'UPA National Common Minimum Programme, 2004', status:'partially_fulfilled', assessment:'NRHM was launched and expanded public-health delivery architecture. The broader access objective is not reducible to programme launch alone.', evidenceStrength:'B', sourceIds:['ncmp-budget','nhm'] },
  { id:'upa-education-spend', party:'congress', commitment:'Raise public spending on education to six per cent of GDP.', document:'UPA National Common Minimum Programme, 2004', status:'not_fulfilled', assessment:'The target was not reached by the end of the UPA period. The consistent WDI/UNESCO series reports government education expenditure at 3.84% of GDP in 2013 and 3.90% in 2014.', evidenceStrength:'B', sourceIds:['ncmp-budget','worldbank-education'] },
  { id:'upa-health-spend', party:'congress', commitment:'Raise public spending on health to at least two per cent of GDP.', document:'UPA National Common Minimum Programme, 2004', status:'not_fulfilled', assessment:'The lower bound of the stated 2–3% target was not reached by the end of the term. The WDI/WHO domestic general-government health series reports 0.87% of GDP in 2013 and 0.86% in 2014.', evidenceStrength:'B', sourceIds:['ncmp-budget','worldbank-health'] },
  { id:'upa-gst-deadline', party:'congress', commitment:'Introduce the Goods and Services Tax from 1 April 2010.', document:'Indian National Congress Manifesto, 2009', status:'not_fulfilled', assessment:'GST was not introduced on the promised date or before the UPA left office in 2014. A constitutional amendment bill was introduced in 2011 but lapsed; GST ultimately came into force in July 2017.', evidenceStrength:'A', sourceIds:['inc-2009','gst'] },
  { id:'nda-gst', party:'bjp', commitment:'Implement a nationwide Goods and Services Tax while addressing states’ concerns.', document:'BJP Election Manifesto, 2014', status:'substantially_fulfilled', assessment:'The constitutional amendment was enacted in 2016 and GST came into force in July 2017 through central and state legislation.', evidenceStrength:'A', sourceIds:['bjp-2014','gst','india-code'] },
  { id:'nda-financial-inclusion', party:'bjp', commitment:'Expand banking and financial-service access for households.', document:'BJP Election Manifesto, 2014', status:'partially_fulfilled', assessment:'PMJDY created a national account-access mission. Fulfilment of the broader inclusion outcome requires usage, credit, insurance and service-quality evidence beyond account opening.', evidenceStrength:'B', sourceIds:['bjp-2014','pmjdy'] },
  { id:'nda-article370', party:'bjp', commitment:'Abrogate Article 370.', document:'BJP Sankalp Patra, 2019', status:'substantially_fulfilled', assessment:'Constitutional orders and parliamentary action in August 2019 substantially altered Article 370’s operation; the Supreme Court upheld the action in 2023.', evidenceStrength:'A', sourceIds:['bjp-2019','article370','india-code'] },
  { id:'nda-uniform-civil-code', party:'bjp', commitment:'Draw a Uniform Civil Code for the country.', document:'BJP manifestos, 2014, 2019 and 2024', status:'not_fulfilled', assessment:'No nationwide Uniform Civil Code had been enacted by the 27 August 2026 cutoff. The 2024 commitment remains within an ongoing parliamentary term, so this is a current-status finding rather than a final term verdict.', evidenceStrength:'A', sourceIds:['bjp-2014','bjp-2019','bjp-2024','india-code'] },
  { id:'nda-national-health', party:'bjp', commitment:'Create a national health-assurance architecture.', document:'BJP Election Manifesto, 2014', status:'partially_fulfilled', assessment:'Ayushman Bharat and PM-JAY created a national hospitalization-cover architecture for eligible families; the broader promise extended beyond this component.', evidenceStrength:'B', sourceIds:['bjp-2014','pmjay'] },
  { id:'nda-data-protection', party:'bjp', commitment:'Provide a personal-data protection legal framework.', document:'BJP Sankalp Patra, 2019', status:'substantially_fulfilled', assessment:'The Digital Personal Data Protection Act was enacted in 2023. Operational completeness depends on commencement and subordinate rules.', evidenceStrength:'A', sourceIds:['bjp-2019','dpdp','india-code'] },
  { id:'nda-simultaneous-elections', party:'bjp', commitment:'Implement One Nation, One Election for the Lok Sabha and state assemblies.', document:'BJP Sankalp Patra, 2024', status:'not_fulfilled', assessment:'Simultaneous elections had not been established by the 27 August 2026 cutoff. Bills were introduced in December 2024 and remained before a Joint Committee, so the promised system was not yet law. The present parliamentary term is ongoing.', evidenceStrength:'A', sourceIds:['bjp-2024','simultaneous-elections-bill'] },
  { id:'nda-new-cities', party:'bjp', commitment:'Initiate building 100 new technology-enabled cities.', document:'BJP Election Manifesto, 2014', status:'not_fulfilled', assessment:'The promise was not delivered as written. The Smart Cities Mission instead selected existing cities through a competitive process and allowed retrofitting, redevelopment, greenfield development or a mix; it did not constitute construction of 100 new cities.', evidenceStrength:'A', sourceIds:['bjp-2014','smart-cities-record'] },
  { id:'nda-housing-2022', party:'bjp', commitment:'Ensure a pucca house by 2022 for every family living in a kutcha house or without housing.', document:'BJP Sankalp Patra, 2019', status:'not_fulfilled', assessment:'The universal 2022 deadline was not met. An official December 2022 release stated that PMAY-G’s initial 2022 timeline had been extended to March 2024, with substantial construction completed but remaining eligible households still outstanding.', evidenceStrength:'A', sourceIds:['bjp-2019','pmay-extension'] },
];

export const legislation = timeline.filter((event) => event.category === 'Laws & Bills');
export const policies = timeline.filter((event) => ['Policies','Social Policy','Infrastructure'].includes(event.category));
export const foreignPolicy = timeline.filter((event) => event.category === 'Foreign Policy');

export const sourceById = (id:string) => sources.find((source) => source.id === id);
export const eventBySlug = (slug:string) => timeline.find((event) => event.slug === slug);
export const promiseById = (id:string) => promises.find((promise) => promise.id === id);
